function initProcessOnlyAnimation() {

  // ? HARD STOP ON MOBILE
  if (window.matchMedia("(max-width: 767px)").matches) {
    return;
  }

  // Wait until GSAP plugins are available
  if (typeof MotionPathPlugin === "undefined" || typeof ScrollTrigger === "undefined") {
