      const targets = document.querySelectorAll("#process-section .target-position");

      if (!section || circles.length === 0) return;

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: section,
          start: "top top",
          end: "+=200%",
          scrub: 1.5,
          pin: true,
          pinSpacing: true,
