        }
      });

      // INITIAL STATE
      gsap.set(circles, { y: 0, opacity: 0 });

      // PHASE 0: DROP
      tl.to(circles, {
        y: 120,
        opacity: 1,
        duration: 0.5,
        ease: "power1.out"
      });
			tl.to("#process-ball", {
  opacity: 0,
