#hero-ball {
    position: absolute;
    will-change: transform, z-index;
}
.hero-pin {
/*     will-change: padding; */
    overflow: hidden !important;
    height: 100vh !important;

}
.frame{
    position: relative;
    z-index: 10;
}


.floating-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 10;
}

.moving-circle {
    position: absolute;
    width: 25px;  
    height: 25px;
    background-color: #F3C01F; 
    border-radius: 50%;
    top: 0;
    left: 50%;
    transform: translate(-50%, 0);
    opacity: 1;
	z-index: 100000;
}

#process-section {
    position: relative;
    overflow: visible !important;
	z-index: 10;
}

.process-card {
    position: relative;
}

.card-video {
    transform: translate(-50%, -50%);
    width: 100%; /* Or the specific size of your SVG icon */
    height: auto;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 5;
}

