.e-n-menu-title-container {
  position: relative;
  padding-top: 32px !important;
}
.e-n-menu-title-container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 32px;
  height: 32px;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -32px);
  opacity: 0;
  transition: all 0.3s ease;
  pointer-events: none;
}
.e-n-menu-title-container:hover::before,
.e-n-menu-item.current-menu-item .e-n-menu-title-container::before {
  opacity: 1;
}
